package com.termux.app.workspace;

import android.app.AlertDialog;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import com.termux.app.TermuxActivity;
import org.json.*;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.function.Consumer;

/** Schedule operations use only explicitly confirmed requests; no app timer runs the commands. */
final class WorkspaceServerSchedules implements AutoCloseable {
    private final TermuxActivity activity;private final ServerConnection connection;private final ExecutorService worker;
    private final List<AlertDialog> dialogs=new ArrayList<>();private boolean closed,busy;
    WorkspaceServerSchedules(TermuxActivity a,ServerConnection c,ExecutorService w){activity=a;connection=c;worker=w;}
    private String t(String ru,String en){return WorkspaceLanguage.code(activity).equals("ru")?ru:en;}
    private void show(AlertDialog d){dialogs.add(d);d.setCanceledOnTouchOutside(false);d.setOnDismissListener(x->dialogs.remove(d));d.show();}
    private LinearLayout body(){LinearLayout b=new LinearLayout(activity);b.setOrientation(LinearLayout.VERTICAL);int p=WorkspaceDialogs.dp(activity,16);b.setPadding(p,0,p,p);return b;}
    private TextView label(LinearLayout b,String text){TextView v=new TextView(activity);v.setText(text);v.setTextColor(WorkspaceDialogs.TEXT);v.setTextSize(14);v.setPadding(0,8,0,8);b.addView(v);return v;}
    private EditText field(LinearLayout b,String name,String value){label(b,name);EditText v=new EditText(activity);v.setTextColor(WorkspaceDialogs.TEXT);v.setText(value);v.setSingleLine(true);b.addView(v);return v;}
    private void request(JSONObject data,Consumer<JSONObject> done){
        if(closed||busy)return;busy=true;AlertDialog waiting=WorkspaceDialogs.builder(activity).setTitle(t("Расписания задач","Task schedules")).setMessage(t("Проверка / выполнение на сервере…","Checking / working on server…")).create();waiting.setCancelable(false);show(waiting);
        worker.execute(()->{JSONObject result=null;String error=null;try{result=connection.schedules(data);}catch(Exception e){String s=e.getMessage();error=s!=null&&s.matches("[A-Z_]{1,80}")?s:"SCHEDULE_ERROR";}JSONObject value=result;String problem=error;activity.runOnUiThread(()->{busy=false;waiting.dismiss();if(closed)return;if(problem!=null){message(t("Операция не выполнена","Operation failed"),problem+"\n"+t("Проверьте Python, доступность планировщика и права. Перед повторным созданием проверьте список: при обрыве связи расписание могло сохраниться.","Check Python, scheduler availability and permissions. Check the list before creating again: a disconnected request may already have saved the schedule."));}else done.accept(value);});});
    }
    private JSONObject op(String name){try{return new JSONObject().put("op",name);}catch(JSONException e){throw new IllegalStateException(e);}}
    private void message(String title,String text){show(WorkspaceDialogs.builder(activity).setTitle(title).setMessage(text).setPositiveButton("OK",null).create());}
    void create(String title,String directory,String command){request(op("capabilities"),caps->{List<String> keys=new ArrayList<>();if(caps.optBoolean("cron"))keys.add("cron");if(caps.optBoolean("systemd"))keys.add("systemd");if(keys.isEmpty()){message(t("Планировщик недоступен","Scheduler unavailable"),t("Нужен crontab или работающий systemd --user. Приложение не устанавливает пакеты и не включает linger автоматически.","Requires crontab or a working systemd --user manager. The app does not install packages or enable linger automatically."));return;}
        LinearLayout body=body();label(body,t("Механизм расписания","Scheduler"));Spinner backend=new Spinner(activity);backend.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,keys));body.addView(backend);EditText plan=field(body,t("Расписание","Schedule"),"*/30 * * * *");
        label(body,t("Cron: 5 полей, например */30 * * * *. systemd: daily, hourly, weekly или *-*-* 03:00:00.","Cron: 5 fields, e.g. */30 * * * *. systemd: daily, hourly, weekly or *-*-* 03:00:00."));label(body,t("Время сервера: ","Server time: ")+caps.optString("time")+" · "+caps.optString("timezone")+(caps.optString("cronTimezone").isEmpty()?"":"\nCRON_TZ: "+caps.optString("cronTimezone")));
        label(body,t("Работает без телефона. Cron требует запущенную службу cron. systemd --user без linger может остановиться после выхода пользователя; автозапуск после перезагрузки зависит от настройки сервера. Команды неинтерактивные, с правами SSH-пользователя, до 1 часа, без &/nohup; окружение/PATH может отличаться от SSH-терминала. Вывод содержит секреты, если команда их печатает.","Runs without the phone. Cron requires a running cron daemon. systemd --user without linger may stop after logout; reboot startup depends on server configuration. Noninteractive commands run as the SSH user, up to 1 hour, no &/nohup; environment/PATH can differ from the SSH terminal. Output may contain secrets printed by the command."));
        backend.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){plan.setText(keys.get(pos).equals("cron")?"*/30 * * * *":"daily");}});
        ScrollView scroll=new ScrollView(activity);scroll.addView(body);AlertDialog form=WorkspaceDialogs.builder(activity).setTitle(t("По расписанию","Scheduled run")).setView(scroll).setPositiveButton(t("Продолжить","Continue"),null).setNegativeButton(t("Отмена","Cancel"),null).create();show(form);form.getButton(-1).setOnClickListener(v->{String schedule=plan.getText().toString().trim(),engine=keys.get(backend.getSelectedItemPosition());if(schedule.isEmpty())return;form.dismiss();String preview=connection.profile.user+"@"+connection.profile.host+"\n"+directory+"\n"+engine+" · "+schedule+"\n\n"+command+"\n\n"+t("Создаёт закрытый каталог ~/.local/share/termux-jobs-schedules-v1 и запись в crontab текущего пользователя либо собственные systemd --user units. Расписания независимы от агента и остаются после его удаления.","Creates a private ~/.local/share/termux-jobs-schedules-v1 directory and a user crontab entry or app-owned systemd --user units. Schedules are independent of the agent and remain after its removal.");show(WorkspaceDialogs.builder(activity).setTitle(t("Создать расписание?","Create schedule?")).setMessage(preview).setPositiveButton(t("Создать","Create"),(x,w)->{try{JSONObject req=op("create").put("backend",engine).put("plan",schedule).put("title",title).put("directory",directory).put("command",command);request(req,r->list());}catch(JSONException e){throw new IllegalStateException(e);}}).setNegativeButton(t("Отмена","Cancel"),null).create());});
    });}
    void list(){request(op("list"),result->{JSONArray entries=result.optJSONArray("schedules");if(entries==null||entries.length()==0){message(t("Расписания задач","Task schedules"),t("Расписаний приложения пока нет.","No app-owned schedules yet."));return;}String[] labels=new String[entries.length()];for(int i=0;i<labels.length;i++){JSONObject s=entries.optJSONObject(i);labels[i]=s.optString("title")+"\n"+s.optString("backend")+" · "+s.optString("plan")+" · "+(s.optBoolean("enabled")?t("Включено","Enabled"):t("Выключено","Disabled"));}show(WorkspaceDialogs.builder(activity).setTitle(t("Расписания задач","Task schedules")).setItems(labels,(d,w)->details(entries.optJSONObject(w))).setPositiveButton(t("Закрыть","Close"),null).create());});}
    private void details(JSONObject entry){String[] items={t("Журнал последнего запуска","Last run log"),entry.optBoolean("enabled")?t("Отключить расписание","Disable schedule"):t("Включить расписание","Enable schedule"),t("Изменить расписание","Edit schedule"),t("Удалить расписание","Delete schedule")};show(WorkspaceDialogs.builder(activity).setTitle(entry.optString("title")).setItems(items,(d,w)->{if(w==0)send("log",entry,r->{JSONObject s=r.optJSONObject("schedule"),last=s==null?null:s.optJSONObject("last");String text=(last==null?"":t("Состояние: ","State: ")+last.optString("state")+"\n")+r.optString("log");TextView log=new TextView(activity);log.setText(text);log.setTextIsSelectable(true);log.setTypeface(Typeface.MONOSPACE);log.setTextColor(WorkspaceDialogs.TEXT);ScrollView scroll=new ScrollView(activity);scroll.addView(log);show(WorkspaceDialogs.builder(activity).setTitle(t("Последний запуск","Last run")).setView(scroll).setPositiveButton("OK",null).create());});
        if(w==1)confirm(entry.optBoolean("enabled")?"disable":"enable",entry);if(w==3)confirm("delete",entry);
        if(w==2){LinearLayout b=body();EditText plan=field(b,t("Новое расписание","New schedule"),entry.optString("plan"));show(WorkspaceDialogs.builder(activity).setTitle(t("Изменить расписание","Edit schedule")).setView(b).setPositiveButton(t("Продолжить","Continue"),(x,y)->{String value=plan.getText().toString().trim();show(WorkspaceDialogs.builder(activity).setTitle(t("Применить расписание?","Apply schedule?")).setMessage(entry.optString("title")+"\n"+entry.optString("backend")+" · "+value).setPositiveButton(t("Да","Yes"),(a,z)->{try{request(op("edit").put("id",entry.getString("id")).put("plan",value),r->list());}catch(JSONException e){throw new IllegalStateException(e);}}).setNegativeButton(t("Нет","No"),null).create());}).setNegativeButton(t("Отмена","Cancel"),null).create());}
    }).setPositiveButton(t("Закрыть","Close"),null).create());}
    private void send(String action,JSONObject entry,Consumer<JSONObject> done){try{request(op(action).put("id",entry.getString("id")),done);}catch(JSONException e){throw new IllegalStateException(e);}}
    private void confirm(String action,JSONObject entry){show(WorkspaceDialogs.builder(activity).setTitle(t("Подтвердить действие","Confirm action")).setMessage(entry.optString("title")+"\n"+action+"\n\n"+t("Меняется только это расписание приложения. Отключение не прерывает уже выполняющуюся команду; удаление выполняющегося расписания заблокировано. При ошибке изменения расписание может остаться выключенным — проверьте список.","Only this app-owned schedule changes. Disabling does not stop a running command; deleting a running schedule is blocked. A failed change may leave it disabled: check the list.")).setPositiveButton(t("Да","Yes"),(d,w)->send(action,entry,r->list())).setNegativeButton(t("Нет","No"),null).create());}
    String serverProfileId(){return connection.profile.id;}
    @Override public void close(){closed=true;for(AlertDialog d:new ArrayList<>(dialogs))d.dismiss();}
}
